# frozen_string_literal: true

require "open3"

# Real compressed fixtures generated by the same established audio tooling
# available on the deployment image. Nothing stubs duration or decoder output.
module SpeechToTextAudioFixtures
  def self.upload(duration: 1)
    @fixtures ||= {}
    bytes = @fixtures[duration] ||= begin
      output, error, status = Open3.capture3(
        "ffmpeg", "-nostdin", "-v", "error", "-f", "lavfi", "-i", "anullsrc=r=8000:cl=mono",
        "-t", duration.to_s, "-c:a", "flac", "-f", "flac", "pipe:1", binmode: true
      )
      raise "FFmpeg fixture generation failed: #{error}" unless status.success?

      output
    end
    { io: StringIO.new(bytes), filename: "silence.flac", content_type: "audio/flac" }
  end
end
